INSERT OR IGNORE INTO global_settings (id,config,updated_at) VALUES ('identity','{"primaryColor":"#31535b","secondaryColor":"#ce994d","typography":"Inter","contactEmail":"","contactPhone":"","socialFacebook":"https://www.facebook.com/p/Santa-Cruz-Grupo-Inmobiliario-61591952656013/","socialInstagram":"https://www.instagram.com/santa_cruz_inmobiliaria/","logoHorizontal":"/identity/livigno-logo.png","logoWhite":"/identity/livigno-logo-negative.png","logoBlack":"/identity/livigno-logo.png","isotipo":"/identity/livigno-logo.png","isotipoWhite":"/identity/livigno-logo-negative.png"}',unixepoch());
INSERT OR IGNORE INTO global_settings (id,config,updated_at) VALUES ('site_homepage','{"hero":{"logo":"/identity/livigno-logo-negative.png","button":"Entrar"},"intro":{"poster":"/homepage/portada.webp","video":"/videos/portada.mp4"},"slides":[{"text":"{{highlight}}, desarrollado por Inmobiliaria Santa Cruz, se ubica en Av. de los Patriotas 555, en el distrito de San Miguel.","highlight":"Livigno 555"},{"text":"Una propuesta residencial de escala cuidada, con 42 unidades distribuidas en una torre de 17 niveles."},{"text":"Departamentos desde 40 m² hasta 127 m², con opciones de hasta 4 dormitorios para diferentes necesidades de vivienda."},{"text":"Disfruta de SUM, grill terrace, gimnasio, coworking, plaza interior, playground, pet zone y bike zone dentro del proyecto."},{"text":"Una fachada vertical con balcones, acabados cálidos y áreas verdes en la parte superior le da al proyecto una presencia moderna y distintiva."}]}',unixepoch());
